; ==================================================================
; MAPPER RUNTIME API
; File: mapper.asm
; Description: Minimal compatibility stubs for simple32k builds
; Target mapper: konami
; ROM mode: simple32k (autoMegaROM=false)
; ==================================================================
;
; This build runs without active mapper writes, so bank switching is not active.
; Keep mapper API labels as no-op stubs so generated gameplay code can
; call the same routines without conditional assembly branches.


; ------------------------------------------------------------------
; mapper_runtime_init
; Initializes runtime mirrors only (no hardware mapper writes).
; ------------------------------------------------------------------
mapper_runtime_init:
    xor a
    ld (mapper_bank_p1_current), a
    ld a, 1
    ld (mapper_bank_p2_current), a
    ld a, 2
    ld (mapper_bank_p3_current), a
    ld a, 3
    ld (mapper_bank_p4_current), a
    ret

; ------------------------------------------------------------------
; API: mapper_set_bank_pX
; Input: A = bank number (stored only for compatibility)
; ------------------------------------------------------------------
mapper_set_bank_p1:
    ld (mapper_bank_p1_current), a
    ret

mapper_set_bank_p2:
    ld (mapper_bank_p2_current), a
    ret

mapper_set_bank_p3:
    ld (mapper_bank_p3_current), a
    ret

mapper_set_bank_p4:
    ld (mapper_bank_p4_current), a
    ret

; ------------------------------------------------------------------
; Save/restore helpers (compatibility only).
; ------------------------------------------------------------------
mapper_push_p1:
    ld a, (mapper_bank_p1_current)
    ld (mapper_saved_bank_p1), a
    ret

mapper_pop_p1:
    ld a, (mapper_saved_bank_p1)
    jp mapper_set_bank_p1

mapper_push_p2:
    ld a, (mapper_bank_p2_current)
    ld (mapper_saved_bank), a
    ret

mapper_pop_p2:
    ld a, (mapper_saved_bank)
    jp mapper_set_bank_p2

mapper_push_p3:
    ld a, (mapper_bank_p3_current)
    ld (mapper_saved_bank_p3), a
    ret

mapper_pop_p3:
    ld a, (mapper_saved_bank_p3)
    jp mapper_set_bank_p3

mapper_push_p4:
    ld a, (mapper_bank_p4_current)
    ld (mapper_saved_bank_p4), a
    ret

mapper_pop_p4:
    ld a, (mapper_saved_bank_p4)
    jp mapper_set_bank_p4

; ------------------------------------------------------------------
; Far call helpers (simple32k no-op bank switch).
; ------------------------------------------------------------------
mapper_call_hl_p1:
    ld de, .return_p1
    push de
    jp (hl)
.return_p1:
    ret

mapper_call_hl_p2:
    jp mapper_call_hl_p1

mapper_call_hl_p3:
    jp mapper_call_hl_p1

mapper_call_hl_p4:
    jp mapper_call_hl_p1

mapper_call_hl_auto:
    jp mapper_call_hl_p1


; ==================================================================
; INTERRUPT TASK SYSTEM - File: interrupt.asm
; Konami-style technique: Hook H.TIMI for 50/60Hz task execution
; ==================================================================

; ==================================================================
; INTERRUPT SYSTEM MEMORY LAYOUT
; Variables are defined in variables.asm (dynamically allocated)
; This avoids RAM overlap with entity system arrays
; ==================================================================
; Slots: task_table (8 slots x 2 bytes), task_0_ptr..task_7_ptr
; State: interrupt_system_enabled, old_htimi_hook, interrupt_counter,
;        task_exec_time, vblank_flag
; ==================================================================

; ==================================================================
; INIT_INTERRUPT_SYSTEM - Install H.TIMI hook
; ==================================================================
; Register Contract:
;   Purpose: Install JP hook on H.TIMI and initialize interrupt task state.
;   Inputs:
;     - None
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - None
;   Register roles:
;     - HL/DE/BC = block copy parameters for hook backup and task table clear
;     - A = enable flag and zeroing value
;   Notes:
;     - Runs with DI/EI, so caller must not assume interrupt state is unchanged.

; Inputs: None
; Outputs: None
; Modifies: AF, BC, DE, HL
; ==================================================================
init_interrupt_system:
    di                          ; Disable interrupts during hook install

    ; --- STEP 1: Save original hook ---
    ld hl, #FD9F                ; H.TIMI address
    ld de, old_htimi_hook       ; Our backup location
    ld bc, 5                    ; Save 5 bytes (JP nnnn + padding)
    ldir                        ; Copy original hook to RAM

    ; --- STEP 2: Install our hook ---
    ; Write "JP interrupt_dispatcher" at FD9F
    ld a, #C3                   ; Opcode for JP
    ld (#FD9F), a               ; Write JP opcode
    ld hl, interrupt_dispatcher ; Address of our ISR
    ld (#FDA0), hl              ; Write address (little-endian)

    ; --- STEP 3: Initialize task table to 0 (all disabled) ---
    ld hl, task_table
    ld de, task_table+1
    ld bc, 15                   ; 8 slots Ç- 2 bytes = 16 bytes - 1
    ld (hl), 0
    ldir                        ; Clear all task pointers

    ; --- STEP 4: Initialize counters ---
    xor a
    ld (interrupt_counter), a
    ld (interrupt_counter+1), a
    ld (vblank_flag), a

    ; --- STEP 5: Mark system as enabled ---
    ld a, 1
    ld (interrupt_system_enabled), a

    ei                          ; Re-enable interrupts
    ret

; ==================================================================
; STOP_INTERRUPT_SYSTEM - Restore original H.TIMI hook
; ==================================================================
; Register Contract:
;   Purpose: Restore original H.TIMI bytes and mark system disabled.
;   Inputs:
;     - None
;   Outputs:
;     - None
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - None
;   Register roles:
;     - HL/DE/BC = LDIR source/destination/count for hook restore
;     - A = zero flag write to interrupt_system_enabled
;   Notes:
;     - Runs with DI/EI for atomic hook restoration.

; Inputs: None
; Outputs: None
; Modifies: AF, BC, DE, HL
; ==================================================================
stop_interrupt_system:
    di                          ; Disable interrupts

    ; Restore original hook
    ld hl, old_htimi_hook       ; Our backup
    ld de, #FD9F                ; H.TIMI location
    ld bc, 5                    ; Restore 5 bytes
    ldir

    ; Mark system as disabled
    xor a
    ld (interrupt_system_enabled), a

    ei                          ; Re-enable interrupts
    ret

; ==================================================================
; INTERRUPT_DISPATCHER - Main ISR (60Hz/50Hz)
; ==================================================================
; Register Contract:
;   Purpose: Dispatch enabled interrupt tasks each VBlank and chain BIOS hook.
;   Inputs:
;     - Triggered by H.TIMI hook
;   Outputs:
;     - interrupt_counter incremented
;     - vblank_flag refreshed
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;     - IX
;     - IY (all restored before exit)
;   Preserved:
;     - DE
;     - IX
;     - IY
;   Register roles:
;     - HL = walks task_table and holds task pointer
;     - B = task slot loop counter
;     - C = temporary low byte for pointer reconstruction
;     - A = enabled checks and pointer validation
;   Notes:
;     - Dispatcher saves/restores DE/IX/IY defensively, reducing coupling with task internals.

; This routine executes on each V-Blank
; CRITICAL: Minimal CPU cycles, maximum efficiency
; Overhead: ~80 cycles base + ~40 cycles per active task
; ==================================================================
interrupt_dispatcher:
    ; --- STEP 1: Save caller-visible registers used by BIOS/user code ---
    push af                     ; 11 cycles
    push hl                     ; 11 cycles
    push bc                     ; 11 cycles
    push de                     ; 11 cycles
    push ix                     ; 15 cycles
    push iy                     ; 15 cycles
    ; Total: 74 cycles fixed prologue overhead

    ; --- STEP 2: Check if system is enabled ---
    ld a, (interrupt_system_enabled)
    or a
    jr z, .exit                 ; If disabled, exit quickly

    ; --- STEP 3: Increment frame counter ---
    ld hl, (interrupt_counter)
    inc hl
    ld (interrupt_counter), hl

    ; --- STEP 3.5: Update VBlank flag (reads VDP status) ---
    call update_vblank_flag

    ; --- STEP 4: Walk through task table ---
    ld hl, task_table           ; HL = pointer to task table
    ld b, 8                     ; 8 slots

.task_loop:
    ; Read task pointer (16-bit address)
    ld a, (hl)                  ; Low byte
    inc hl
    ld c, a
    ld a, (hl)                  ; High byte
    inc hl
    or c                        ; Check if pointer == 0
    jr z, .next_task            ; Skip if disabled (pointer == 0)

    ; Valid pointer: execute task
    dec hl
    dec hl                      ; Back to low byte
    push bc                     ; Save loop counter
    push hl                     ; Save table position

    ; Load task address into HL
    ld c, (hl)                  ; Low byte
    inc hl
    ld h, (hl)                  ; High byte
    ld l, c                     ; HL = task address

    ; Call task using JP (HL) pattern (faster than indirect CALL)
    call .call_task             ; Call the task

    pop hl                      ; Restore table position
    pop bc                      ; Restore loop counter
    inc hl
    inc hl                      ; Advance to next slot
    jr .continue_loop

.next_task:
    ; Nothing to do, HL already points to next slot

.continue_loop:
    djnz .task_loop             ; Loop 8 times

.exit:
    ; --- STEP 5: Restore registers ---
    pop iy                      ; 14 cycles
    pop ix                      ; 14 cycles
    pop de                      ; 10 cycles
    pop bc                      ; 10 cycles
    pop hl                      ; 10 cycles
    pop af                      ; 10 cycles

    ; --- STEP 6: Return from interrupt ---
    ; For H.TIMI we should chain to the original hook (best compatibility)
    ; and let the BIOS interrupt handler manage EI/RETI.
    jp old_htimi_hook

; Helper for indirect call
.call_task:
    jp (hl)                     ; Jump to task (task will RET back here)

; ==================================================================
; TASK MANAGEMENT FUNCTIONS
; ==================================================================

; ==================================================================
; NOTE: wait_vblank function removed - use HALT directly in game loop
; HALT is more efficient (no call/ret overhead)
; ==================================================================

; ==================================================================
; UPDATE_VBLANK_FLAG - For interrupt dispatcher use only
; ==================================================================
; Register Contract:
;   Purpose: Read VDP status register and latch VBlank state in RAM flag.
;   Inputs:
;     - None
;   Outputs:
;     - vblank_flag = 0/1
;   Clobbers:
;     - AF (internally saved/restored)
;   Preserved:
;     - AF, BC, DE, HL
;   Register roles:
;     - A = VDP status read and boolean conversion

; Updates vblank_flag only if we're actually in VBlank
; Called from interrupt_dispatcher
; Inputs: None
; Outputs: None
; Modifies: AF
; ==================================================================
update_vblank_flag:
    push af
    in a, (#99)                 ; Read VDP status register
    bit 7, a                    ; Are we in VBlank?
    jr z, .not_in_vblank
    ld a, 1
    ld (vblank_flag), a
    jr .uvf_done
.not_in_vblank:
    xor a
    ld (vblank_flag), a
.uvf_done:
    pop af
    ret

; ==================================================================
; ENABLE_TASK - Activate a task in the system
; ==================================================================
; Register Contract:
;   Purpose: Store routine pointer into task_table slot.
;   Inputs:
;     - A = task slot (0-7)
;     - HL = task routine address
;   Outputs:
;     - task_table[slot] = HL
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - None
;   Register roles:
;     - A = slot validation and offset math
;     - DE = holds routine address while HL is repurposed as slot pointer
;     - BC = task_table base address
;     - HL = slot address calculation / pointer write

; Inputs:
;   A = task slot (0-7)
;   HL = address of task routine
; Outputs: None
; Modifies: AF, BC, DE, HL
; ==================================================================
enable_task:
    ; Validate slot (0-7)
    cp 8
    ret nc                      ; Return if slot >= 8

    ; Calculate offset in table: slot * 2
    add a, a                    ; A = slot * 2
    ld e, a
    ld d, 0
    ld bc, task_table
    ex de, hl                   ; HL = offset, DE = task address
    add hl, bc                  ; HL = task_table + offset

    ; Write task address
    ex de, hl                   ; HL = task address, DE = slot location
    ld a, l
    ld (de), a                  ; Write low byte
    inc de
    ld a, h
    ld (de), a                  ; Write high byte

    ret

; ==================================================================
; DISABLE_TASK - Deactivate a task
; ==================================================================
; Register Contract:
;   Purpose: Clear routine pointer in selected task slot.
;   Inputs:
;     - A = task slot (0-7)
;   Outputs:
;     - task_table[slot] = 0
;   Clobbers:
;     - AF
;     - DE
;     - HL
;   Preserved:
;     - BC
;   Register roles:
;     - A = slot validation and zero value for clearing
;     - HL = destination slot pointer
;     - DE = computed slot offset

; Inputs:
;   A = task slot (0-7)
; Outputs: None
; Modifies: AF, DE, HL
; ==================================================================
disable_task:
    ; Validate slot
    cp 8
    ret nc

    ; Calculate offset
    add a, a                    ; A = slot * 2
    ld e, a
    ld d, 0
    ld hl, task_table
    add hl, de                  ; HL = task_table + offset

    ; Write 0 (disable)
    xor a
    ld (hl), a                  ; Low byte = 0
    inc hl
    ld (hl), a                  ; High byte = 0

    ret

; ==================================================================
; GET_FRAME_COUNT - Get frame counter value
; ==================================================================
; Register Contract:
;   Purpose: Expose current 16-bit interrupt frame counter.
;   Inputs:
;     - None
;   Outputs:
;     - HL = interrupt_counter
;   Clobbers:
;     - HL
;   Preserved:
;     - AF
;     - BC
;     - DE
;   Register roles:
;     - HL = loaded return value

; Inputs: None
; Outputs: HL = frame count (16-bit)
; Modifies: HL
; ==================================================================
get_frame_count:
    ld hl, (interrupt_counter)
    ret

; ==================================================================
; INIT_DEFAULT_TASKS_FROM_PLAN - Register engine-selected IRQ tasks
; ==================================================================
; Register Contract:
;   Purpose: Enable the IRQ task set selected by the engine execution plan.
;   Inputs:
;     - None
;   Outputs:
;     - task_table updated for all enabled-at-boot tasks
;   Clobbers:
;     - AF
;     - HL
;   Preserved:
;     - BC
;     - DE
;   Register roles:
;     - A = task slot
;     - HL = task routine address
;   Notes:
;     - Calls enable_task once per enabled task.
init_default_tasks_from_plan:
    ret

; ==================================================================
; DEFAULT INTERRUPT TASKS (60Hz Execution)
; ==================================================================

; ==================================================================
; TASK_UPDATE_INPUT - Joystick/Cursor polling at 60Hz
; ==================================================================
; This task guarantees responsive input (no missed button presses)
; Compatible with update_input_component existing function
; ==================================================================
; Register Contract:
;   Purpose: Poll joystick + keyboard fallback and update input state buffers.
;   Inputs:
;     - Reads hardware via FAST_GTSTCK / FAST_GTTRIG / FAST_SNSMAT
;   Outputs:
;     - input_state, prev_input_state, input_btn_curr, input_btn_prev, input_fire
;   Clobbers:
;     - AF
;     - BC
;     - DE
;   Preserved:
;     - AF
;     - BC
;     - DE (by push/pop wrapper)
;     - HL
;   Register roles:
;     - A = hardware reads and final scalar writes
;     - B = direction accumulator
;     - D = button bitmask and keyboard direction flags
;     - E = temporary keyboard row bits
;   Notes:
;     - Wrapper preserves caller-visible regs despite internal mutation.
task_update_input:
    push af
    push bc
    push de

    ; Save previous state
    ld a, (input_state)
    ld (prev_input_state), a
    ld a, (input_btn_curr)
    ld (input_btn_prev), a

    ; Read joystick direction first (priority source, direct hardware)
    xor a                       ; Joystick 0
    call FAST_GTSTCK            ; Direct hardware read
    ld b, a                     ; B = joystick direction
    or a
    jr nz, .dir_ready

    ; Fallback to keyboard cursor keys (row 8, direct matrix read)
    ld a, 8
    call FAST_SNSMAT            ; Active low bits
    ld e, a
    xor a
    ld d, a                     ; D = direction flags: 0=none
    bit 5, e                    ; Up
    jr nz, .kbd_no_up
    set 0, d
.kbd_no_up:
    bit 6, e                    ; Down
    jr nz, .kbd_no_down
    set 1, d
.kbd_no_down:
    bit 4, e                    ; Left
    jr nz, .kbd_no_left
    set 2, d
.kbd_no_left:
    bit 7, e                    ; Right
    jr nz, .kbd_no_right
    set 3, d
.kbd_no_right:
    xor a
    bit 0, d
    jr z, .kbd_check_down
    bit 3, d
    jr nz, .kbd_upright
    bit 2, d
    jr nz, .kbd_upleft
    ld a, STICK_UP
    jr .kbd_done
.kbd_upright:
    ld a, STICK_UPRIGHT
    jr .kbd_done
.kbd_upleft:
    ld a, STICK_UPLEFT
    jr .kbd_done
.kbd_check_down:
    bit 1, d
    jr z, .kbd_check_lr
    bit 3, d
    jr nz, .kbd_downright
    bit 2, d
    jr nz, .kbd_downleft
    ld a, STICK_DOWN
    jr .kbd_done
.kbd_downright:
    ld a, STICK_DOWNRIGHT
    jr .kbd_done
.kbd_downleft:
    ld a, STICK_DOWNLEFT
    jr .kbd_done
.kbd_check_lr:
    bit 2, d
    jr z, .kbd_check_right
    ld a, STICK_LEFT
    jr .kbd_done
.kbd_check_right:
    bit 3, d
    jr z, .kbd_done
    ld a, STICK_RIGHT
.kbd_done:
    ld b, a
.dir_ready:
    ; Normalize diagonals to cardinal directions for runtime stability
    ; UP+RIGHT/DOWN+RIGHT -> RIGHT, UP+LEFT/DOWN+LEFT -> LEFT
    ld a, b
    cp STICK_UPRIGHT
    jr z, .dir_norm_right
    cp STICK_DOWNRIGHT
    jr z, .dir_norm_right
    cp STICK_UPLEFT
    jr z, .dir_norm_left
    cp STICK_DOWNLEFT
    jr z, .dir_norm_left
    jr .dir_norm_done
.dir_norm_right:
    ld a, STICK_RIGHT
    jr .dir_norm_store
.dir_norm_left:
    ld a, STICK_LEFT
.dir_norm_store:
    ld b, a
.dir_norm_done:
    xor a                       ; Joystick 0
    call FAST_GTTRIG            ; A = #FF if pressed, 0 if not
    ld d, 0                     ; D = button bitmask
    or a
    jr z, .no_fire              ; Jump if NOT pressed (A=0)
    ld d, INPUT_BTN_FIRE
    ld a, 1                     ; Fire pressed
    ld (input_fire), a
    jr .fire_done
.no_fire:
    ; Keyboard fallback for fire (SPACE, row 8 bit 0, active low)
    ld a, 8
    call FAST_SNSMAT
    bit 0, a
    jr nz, .fire_released
    ld d, INPUT_BTN_FIRE
    ld a, 1
    ld (input_fire), a
    jr .fire_done
.fire_released:
    xor a                       ; Fire not pressed
    ld (input_fire), a
.fire_done:
    ld a, b
    ld (input_state), a
    ld a, d
    ld (input_btn_curr), a

    pop de
    pop bc
    pop af
    ret

; ==================================================================
; TASK_UPDATE_PHYSICS - Apply vx, vy -> X, Y (OPTIMIZED)
; ==================================================================
; Only calls physics systems that are actually used in this project
; ==================================================================
; Register Contract:
;   Purpose: Run selected physics component systems in deterministic order.
;   Inputs:
;     - Entity/component RAM tables
;   Outputs:
;     - Entity motion state updated
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - AF
;     - BC
;     - DE
;     - HL (by push/pop wrapper)
;   Register roles:
;     - Registers are scratch during component calls; wrapper restores caller context.
task_update_physics:
    push af
    push bc
    push de
    push hl

    ; Keep system loops in sync with current component masks
    call rebuild_used_entity_list
    call update_jump_component      ; Jump impulse
    call update_movement_component  ; Movement/velocity
    call update_gravity_component   ; Gravity acceleration
    call update_position_component  ; Apply velocity to position

    pop hl
    pop de
    pop bc
    pop af
    ret

; ==================================================================
; TASK_UPDATE_COLLISION - Collision detection
; ==================================================================
; Detects collisions using collision layers (bitmask system)
; AABB collision for 16x16 sprites
; ==================================================================
; Register Contract:
;   Purpose: Interrupt task wrapper for collision system (placeholder).
;   Inputs:
;     - Entity collision data
;   Outputs:
;     - Collision flags/tables (when implemented)
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - AF
;     - BC
;     - DE
;     - HL (by push/pop wrapper)
task_update_collision:
    push af
    push bc
    push de
    push hl

    ; TODO: Implement collision detection
    ; Loop over entities with COMP_MASK_COLLISION
    ; Check: collisionLayer & collidesWith for each pair
    ; AABB test: |X1-X2| < 16 && |Y1-Y2| < 16

    pop hl
    pop de
    pop bc
    pop af
    ret

; ==================================================================
; TASK_UPDATE_SPRITES - Update sprites to VRAM
; ==================================================================
; WARNING: This task is HEAVY (~800 cycles)
; Consider executing every N frames instead of every frame
; ==================================================================
; Register Contract:
;   Purpose: Interrupt-safe wrapper for sprite SAT upload routine.
;   Inputs:
;     - Sprite component buffers
;   Outputs:
;     - VRAM sprite attribute/pattern tables updated
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - AF
;     - BC
;     - DE
;     - HL (by push/pop wrapper)
task_update_sprites:
    push af
    push bc
    push de
    push hl

    ; Call existing sprite update function
    call update_sprites_to_vram

    pop hl
    pop de
    pop bc
    pop af
    ret

; ==================================================================
; TASK_UPDATE_MUSIC - Fixed-rate audio tick
; ==================================================================
; Keeps tracker and state-machine audio tied to H.TIMI instead of variable-cost loops
; ==================================================================
; Register Contract:
;   Purpose: Interrupt-safe wrapper for tracker/state-machine audio tick.
;   Inputs:
;     - Music engine RAM state and state-machine sound cursors
;   Outputs:
;     - PSG state advanced once per VBlank
;   Clobbers:
;     - AF
;     - BC
;     - DE
;     - HL
;   Preserved:
;     - AF
;     - BC
;     - DE
;     - HL (by push/pop wrapper)
task_update_music:
    push af
    push bc
    push de
    push hl

    call music_update
    call SM_UpdateSound

    pop hl
    pop de
    pop bc
    pop af
    ret

