; ==================================================================
; TILE PATTERN DATA
; File: patterns.asm
; Description: Tile pattern definitions for MSX Screen 2
; 12 tiles detected
; ==================================================================

PATTERN_DATA_BANK EQU ((tile_pattern_bank0 - #4000) / #2000)

; ==================================================================
; TILE PATTERN BANK 0 (Base patterns)
; ==================================================================
tile_pattern_bank0:
    ; Tile 0: rajol1 (16x16px = 2×2 chars = 4 MSX characters)
    ; Character layout: 2×2 grid
    ; Row 0: Char0 Char1 
    ; Row 1: Char2 Char3 
    db #00, #7F, #7F, #00, #E0, #EC, #00, #74, #00, #EF, #EF, #00, #11, #11, #00, #22, #71, #00, #F0, #F1, #00, #70, #70, #70, #41, #00, #11, #02, #00, #05, #20, #C2
    ; Tile 1: senefa1 (8x8px = 1×1 chars = 1 MSX characters)
    db #00, #00, #FF, #55, #FF, #AA, #FF, #00
    ; Tile 2: corda (8x8px = 1×1 chars = 1 MSX characters)
    db #18, #30, #30, #19, #18, #0C, #0C, #98
    ; Tile 3: gema (8x8px = 1×1 chars = 1 MSX characters)
    db #80, #18, #3C, #7E, #7E, #34, #18, #01
    ; Tile 4: gema_f0 (8x8px = 1×1 chars = 1 MSX characters)
    db #01, #18, #3C, #7E, #7E, #34, #18, #80
    ; Tile 5: rajola (8x8px = 1×1 chars = 1 MSX characters)
    db #FE, #FF, #FF, #DF, #AF, #DF, #FF, #7F
    ; Tile 6: rajol_terra5 (16x16px = 2×2 chars = 4 MSX characters)
    ; Character layout: 2×2 grid
    ; Row 0: Char0 Char1 
    ; Row 1: Char2 Char3 
    db #00, #7F, #7F, #00, #80, #20, #00, #42, #00, #EF, #EF, #00, #09, #80, #00, #42, #08, #00, #02, #10, #00, #00, #00, #02, #09, #00, #00, #40, #00, #04, #01, #00
    ; Tile 7: gem_extra_jump (8x8px = 1×1 chars = 1 MSX characters)
    db #00, #00, #38, #38, #38, #00, #00, #00
    ; Tile 8: rajol_vermell (8x8px = 1×1 chars = 1 MSX characters)
    db #00, #FF, #A9, #FF, #A5, #FF, #00, #00
    ; Tile 9: gem_extra_jump_f0 (8x8px = 1×1 chars = 1 MSX characters)
    db #00, #10, #38, #7C, #38, #10, #00, #00
    ; Tile 10: elevador1 (8x8px = 1×1 chars = 1 MSX characters)
    db #D0, #D0, #C0, #C0, #FF, #C0, #C0, #D0
    ; Tile 11: elevador2 (8x8px = 1×1 chars = 1 MSX characters)
    db #0B, #0B, #03, #03, #FF, #03, #03, #03


; ==================================================================
; PATTERN LOADING FUNCTIONS
; ==================================================================
load_pattern_bank0:
    ; Load pattern bank 0 to VRAM (base patterns)
    ; Fast direct port access (no BIOS overhead)
    call mapper_push_p2
    ld a, PATTERN_DATA_BANK
    call mapper_set_bank_p2
    ld hl, tile_pattern_bank0
    ld de, CHRTBL2 + (128 * 8)    ; VRAM pattern table bank 0 (start at char 128)
    ld bc, 144    ; Total bytes for all tile characters (16x16 tiles = 4 chars each)
    call FAST_LDIRVM              ; Fast VRAM write (direct port access)
